CREATE TABLE public.report_prices (report_key text PRIMARY KEY CHECK(report_key IN ('verification','shareholders','statements','valuation','pnl','risk','credit')), price_type text NOT NULL DEFAULT 'paid' CHECK(price_type IN ('paid','free','on_request')), price_thb numeric, free_until date, free_for_sellers boolean NOT NULL DEFAULT true, free_for_buyers boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid);
GRANT SELECT ON public.report_prices TO authenticated; GRANT ALL ON public.report_prices TO service_role;
ALTER TABLE public.report_prices ENABLE ROW LEVEL SECURITY;
CREATE POLICY report_prices_read ON public.report_prices FOR SELECT TO authenticated USING(true);
INSERT INTO public.report_prices(report_key,price_type,price_thb) SELECT k,t,n FROM (VALUES ('verification','paid',4900::numeric),('shareholders','paid',1500),('statements','paid',10000),('valuation','paid',15000),('pnl','paid',10000),('risk','paid',12000),('credit','on_request',NULL)) v(k,t,n);
CREATE TABLE public.report_price_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),report_key text NOT NULL REFERENCES public.report_prices(report_key),at timestamptz NOT NULL DEFAULT now(),by_user uuid,summary text NOT NULL,changes jsonb NOT NULL DEFAULT '{}');
GRANT SELECT ON public.report_price_history TO authenticated; GRANT ALL ON public.report_price_history TO service_role;
ALTER TABLE public.report_price_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY report_price_history_admin ON public.report_price_history FOR SELECT TO authenticated USING(public.is_control(auth.uid()) AND public.is_account_admin(auth.uid()));
INSERT INTO public.report_price_history(report_key,summary) SELECT report_key,CASE WHEN price_type='on_request' THEN 'On request: quoted by an analyst' ELSE 'Price '||price_thb::text||' THB, from the price list' END FROM public.report_prices;
CREATE TABLE public.report_price_changes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),report_key text NOT NULL REFERENCES public.report_prices(report_key),new_values jsonb NOT NULL,effective_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,status text NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','applied','cancelled')));
GRANT SELECT ON public.report_price_changes TO authenticated; GRANT ALL ON public.report_price_changes TO service_role;
ALTER TABLE public.report_price_changes ENABLE ROW LEVEL SECURITY;
CREATE POLICY report_price_changes_admin ON public.report_price_changes FOR SELECT TO authenticated USING(public.is_control(auth.uid()) AND public.is_account_admin(auth.uid()));
CREATE UNIQUE INDEX report_one_schedule ON public.report_price_changes(report_key) WHERE status='scheduled';
ALTER TABLE public.plan_reports ADD COLUMN free_per_quarter integer NOT NULL DEFAULT 0 CHECK(free_per_quarter BETWEEN 0 AND 20);
ALTER TABLE public.plan_reports DROP CONSTRAINT plan_reports_report_key_check;
ALTER TABLE public.plan_reports ADD CONSTRAINT plan_reports_report_key_check CHECK(report_key IN ('fs5','fs3','fs1','verification','shareholders','statements','valuation','pnl','risk','credit'));
INSERT INTO public.plan_reports(plan_id,report_key,mode,per_term,free_per_quarter) SELECT p.id,r.report_key,'none',NULL,CASE WHEN p.role='seller' THEN CASE p.key WHEN 'promo_pro' THEN 1 WHEN 'pro' THEN 2 WHEN 'executive' THEN 5 ELSE 0 END ELSE CASE p.key WHEN 'basic' THEN 1 WHEN 'investor' THEN 2 WHEN 'institutional' THEN 5 ELSE 0 END END FROM public.plans p CROSS JOIN public.report_prices r WHERE p.role IN ('seller','buyer') ON CONFLICT(plan_id,report_key) DO UPDATE SET free_per_quarter=EXCLUDED.free_per_quarter;
COMMENT ON COLUMN public.plan_reports.mode IS 'DEPRECATED for report allowances: use free_per_quarter';
COMMENT ON COLUMN public.plan_reports.per_term IS 'DEPRECATED: use free_per_quarter with subscription-anchored quarter';
COMMENT ON COLUMN public.plans.verification_mode IS 'DEPRECATED for inclusion: use plan_reports.free_per_quarter';
COMMENT ON COLUMN public.plans.verification_price_thb IS 'DEPRECATED: report_prices is the price source';
ALTER TABLE public.buyer_report_access DROP CONSTRAINT buyer_report_access_via_check;
ALTER TABLE public.buyer_report_access ADD CONSTRAINT buyer_report_access_via_check CHECK(via IN ('plan','paid','contract','free_period'));
CREATE OR REPLACE FUNCTION public.report_quarter_start(_start timestamptz,_now timestamptz DEFAULT now()) RETURNS timestamptz LANGUAGE plpgsql STABLE SET search_path=public AS $$ DECLARE s timestamp:=_start AT TIME ZONE 'Asia/Bangkok'; n timestamp:=_now AT TIME ZONE 'Asia/Bangkok'; k integer; q timestamp; BEGIN k:=greatest(0,floor(((extract(year FROM n)-extract(year FROM s))*12+extract(month FROM n)-extract(month FROM s))/3)::int);q:=s+make_interval(months=>3*k);IF q>n AND k>0 THEN q:=s+make_interval(months=>3*(k-1));END IF;RETURN q AT TIME ZONE 'Asia/Bangkok';END $$;
CREATE OR REPLACE FUNCTION public.report_quote(_uid uuid,_key text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.report_prices; s public.subscriptions; r text; q timestamptz; n int:=0; used int:=0; free boolean; BEGIN SELECT * INTO p FROM public.report_prices WHERE report_key=_key;IF NOT FOUND THEN RAISE EXCEPTION 'Report unavailable';END IF;r:=public.account_role_of(_uid);SELECT * INTO s FROM public.subscriptions WHERE user_id=_uid;IF s.id IS NOT NULL AND s.status='active' AND (s.term_end IS NULL OR s.term_end>now()) AND s.term_start<=now() THEN q:=public.report_quarter_start(s.term_start);SELECT pr.free_per_quarter INTO n FROM public.plan_reports pr JOIN public.plans pl ON pl.id=pr.plan_id WHERE pr.plan_id=s.plan_id AND pr.report_key=_key AND pl.role=r AND pl.status='live';SELECT count(*) INTO used FROM public.plan_usage WHERE user_id=_uid AND kind='report:'||_key AND term_start=q;END IF;n:=coalesce(n,0);free:=p.price_type='free' AND (p.free_until IS NULL OR p.free_until>=(now() AT TIME ZONE 'Asia/Bangkok')::date) AND CASE r WHEN 'seller' THEN p.free_for_sellers WHEN 'buyer' THEN p.free_for_buyers ELSE false END;RETURN jsonb_build_object('price',p.price_thb,'priceType',p.price_type,'freeUntil',p.free_until,'freePeriod',free,'total',n,'left',greatest(0,n-used),'quarterStart',q,'method',CASE WHEN free THEN 'Free period' WHEN n>used THEN 'Plan' WHEN p.price_type='on_request' THEN 'Quote' ELSE 'Manual' END,'amount',CASE WHEN free OR n>used THEN 0 WHEN p.price_type='on_request' THEN NULL ELSE round(p.price_thb*1.07,2) END);END $$;
REVOKE ALL ON FUNCTION public.report_quote(uuid,text) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.report_quote(uuid,text) TO service_role;
CREATE OR REPLACE FUNCTION public.apply_report_price_edit(_key text,_values jsonb,_by uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE old public.report_prices; n public.report_prices; a record; summary_text text; delta jsonb; BEGIN IF NOT public.is_control(_by) OR NOT public.is_account_admin(_by) THEN RAISE EXCEPTION 'Control Admin only';END IF;SELECT * INTO old FROM public.report_prices WHERE report_key=_key FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Report unavailable';END IF;SELECT * INTO n FROM jsonb_populate_record(old,_values-'report_key'-'updated_at'-'updated_by'-'allowances'-'_summary');IF n.price_type NOT IN ('paid','free','on_request') THEN RAISE EXCEPTION 'Invalid price type';END IF;IF n.price_type<>'on_request' AND coalesce(n.price_thb,0)<=0 THEN RAISE EXCEPTION 'Enter the price';END IF;IF n.price_type='free' AND NOT(n.free_for_sellers OR n.free_for_buyers) THEN RAISE EXCEPTION 'Choose who gets it free';END IF;IF n.price_type='free' AND n.free_until<(now() AT TIME ZONE 'Asia/Bangkok')::date THEN RAISE EXCEPTION 'Pick a day from today on';END IF;delta:=jsonb_build_object('old',to_jsonb(old),'new',to_jsonb(n),'allowances',_values->'allowances');UPDATE public.report_prices SET price_type=n.price_type,price_thb=n.price_thb,free_until=n.free_until,free_for_sellers=n.free_for_sellers,free_for_buyers=n.free_for_buyers,updated_at=now(),updated_by=_by WHERE report_key=_key;FOR a IN SELECT key,value FROM jsonb_each_text(coalesce(_values->'allowances','{}')) LOOP IF a.value::int NOT BETWEEN 0 AND 20 OR NOT EXISTS(SELECT 1 FROM public.plans WHERE id=a.key::uuid AND role IN ('seller','buyer')) THEN RAISE EXCEPTION 'Invalid plan allowance';END IF;INSERT INTO public.plan_reports(plan_id,report_key,mode,free_per_quarter) VALUES(a.key::uuid,_key,'none',a.value::int) ON CONFLICT(plan_id,report_key) DO UPDATE SET free_per_quarter=excluded.free_per_quarter;UPDATE public.plans SET updated_at=now() WHERE id=a.key::uuid;END LOOP;summary_text:=coalesce(_values->>'_summary','Report price updated');INSERT INTO public.report_price_history(report_key,by_user,summary,changes) VALUES(_key,_by,summary_text,delta);INSERT INTO public.security_events(user_id,event_type,details) VALUES(_by,'ROLE_CHANGE',jsonb_build_object('action','report_price_published','report',_key,'changes',delta));END $$;
REVOKE ALL ON FUNCTION public.apply_report_price_edit(text,jsonb,uuid) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.apply_report_price_edit(text,jsonb,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.apply_scheduled_report_changes() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.report_price_changes;n int:=0;BEGIN FOR c IN SELECT * FROM public.report_price_changes WHERE status='scheduled' AND effective_at<=now() ORDER BY effective_at FOR UPDATE SKIP LOCKED LOOP BEGIN PERFORM public.apply_report_price_edit(c.report_key,c.new_values,c.created_by);UPDATE public.report_price_changes SET status='applied' WHERE id=c.id;n:=n+1;EXCEPTION WHEN OTHERS THEN RAISE WARNING 'Report schedule % failed: %',c.id,SQLERRM;END;END LOOP;RETURN n;END $$;
REVOKE ALL ON FUNCTION public.apply_scheduled_report_changes() FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.apply_scheduled_report_changes() TO service_role;
SELECT cron.schedule('apply-scheduled-plans-bangkok-midnight','0 17 * * *','select public.apply_scheduled_plan_changes(); select public.apply_scheduled_report_changes();');
CREATE OR REPLACE FUNCTION public.create_report_order(_uid uuid,_company uuid,_kind text,_due timestamptz) RETURNS public.report_orders LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.report_orders; k text; q jsonb; BEGIN IF NOT public.verification_owner(_uid,_company) OR public.account_role_of(_uid) NOT IN ('seller','admin') THEN RAISE EXCEPTION 'Not your company';END IF;PERFORM pg_advisory_xact_lock(hashtextextended('report:'||_uid::text,0));SELECT * INTO o FROM public.report_orders WHERE startup_id=_company AND kind=_kind AND status IN ('paid','generated') ORDER BY paid_at DESC LIMIT 1;IF FOUND THEN RETURN o;END IF;k:=CASE WHEN _kind='financials' THEN 'statements' ELSE _kind END;IF _kind='bundle' THEN q:=jsonb_build_object('amount',22000,'method','Manual');ELSE q:=public.report_quote(_uid,k);END IF;IF q->>'method'='Quote' THEN RAISE EXCEPTION 'Ask PitchSnack for a quote';END IF;IF q->>'method'='Plan' THEN INSERT INTO public.plan_usage(user_id,kind,ref,term_start) VALUES(_uid,'report:'||k,_company::text,(q->>'quarterStart')::timestamptz);END IF;INSERT INTO public.report_orders(startup_id,kind,amount,currency,status,paid_at,due_at,method,payment_ref,ordered_by) VALUES(_company,_kind,(q->>'amount')::numeric,'THB','paid',now(),_due,q->>'method','MAN-'||substr(gen_random_uuid()::text,1,8),_uid) RETURNING * INTO o;RETURN o;END $$;
REVOKE ALL ON FUNCTION public.create_report_order(uuid,uuid,text,timestamptz) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.create_report_order(uuid,uuid,text,timestamptz) TO service_role;
CREATE OR REPLACE FUNCTION public.reports_open_plan(_buyer uuid,_pipeline uuid,_report text,_plan_key text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.deal_pipelines;q jsonb;a public.buyer_report_access;via_text text;BEGIN IF public.account_role_of(_buyer)<>'buyer' OR NOT public.reports_pipeline_nda(_pipeline,_buyer) THEN RAISE EXCEPTION 'An approved active NDA is required';END IF;SELECT * INTO d FROM public.deal_pipelines WHERE id=_pipeline FOR SHARE;PERFORM pg_advisory_xact_lock(hashtextextended('report:'||_buyer::text,0));IF NOT EXISTS(SELECT 1 FROM public.report_prices WHERE report_key=_report) THEN RAISE EXCEPTION 'Invalid report';END IF;SELECT * INTO a FROM public.buyer_report_access WHERE company_id=d.startup_id AND buyer_id=_buyer AND report_key=_report;IF FOUND THEN RETURN jsonb_build_object('reopened',true);END IF;IF EXISTS(SELECT 1 FROM public.report_shares WHERE pipeline_id=_pipeline AND buyer_id=_buyer AND revoked_at IS NULL AND (_report=ANY(report_keys) OR (_report='statements' AND financials) OR (_report='valuation' AND valuation))) THEN RETURN jsonb_build_object('shared',true);END IF;q:=public.report_quote(_buyer,_report);IF q->>'method' NOT IN ('Plan','Free period') THEN RAISE EXCEPTION 'No free reports left this quarter';END IF;IF q->>'method'='Plan' THEN INSERT INTO public.plan_usage(user_id,kind,ref,term_start) SELECT _buyer,'report:'||_report,d.startup_id::text,(q->>'quarterStart')::timestamptz WHERE NOT EXISTS(SELECT 1 FROM public.plan_usage WHERE user_id=_buyer AND kind='report:'||_report AND ref=d.startup_id::text AND term_start=(q->>'quarterStart')::timestamptz);END IF;via_text:=CASE WHEN q->>'method'='Free period' THEN 'free_period' ELSE 'plan' END;INSERT INTO public.buyer_report_access(company_id,buyer_id,pipeline_id,report_key,via) VALUES(d.startup_id,_buyer,_pipeline,_report,via_text);IF _report='verification' THEN INSERT INTO public.company_verifications(company_id,status,requested_by,started_at,ready_by) VALUES(d.startup_id,'checking',_buyer,now(),public.verification_business_due(now(),1)) ON CONFLICT(company_id) DO UPDATE SET status=CASE WHEN company_verifications.status IN ('not_ordered','waiting_payment') THEN 'checking' ELSE company_verifications.status END;ELSE INSERT INTO public.company_report_records(company_id,report_key,status,ready_by) VALUES(d.startup_id,_report,'in_progress',public.verification_business_due(now(),1)) ON CONFLICT(company_id,report_key) DO NOTHING;END IF;RETURN jsonb_build_object('reopened',false,'method',q->>'method');END $$;
REVOKE ALL ON FUNCTION public.reports_open_plan(uuid,uuid,text,text) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.reports_open_plan(uuid,uuid,text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.verification_open_pipeline(_uid uuid,_company uuid,_pipeline uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.verification_pipeline_valid(_uid,_company,_pipeline) THEN RAISE EXCEPTION 'An approved, valid NDA is required';END IF;RETURN public.reports_open_plan(_uid,_pipeline,'verification','verification');END $$;
CREATE OR REPLACE FUNCTION public.verification_start_included(_company uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN;END $$;
COMMENT ON FUNCTION public.verification_start_included(uuid) IS 'DEPRECATED: checks begin on explicit report orders; reads never spend allowance';
CREATE OR REPLACE FUNCTION public.verification_can_read(_uid uuid,_company uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.verification_owner(_uid,_company) OR (public.verification_nda_valid(_uid,_company) AND (EXISTS(SELECT 1 FROM public.buyer_report_access WHERE buyer_id=_uid AND company_id=_company AND report_key='verification') OR EXISTS(SELECT 1 FROM public.verification_access a WHERE a.buyer_account_id=_uid AND a.company_id=_company AND (a.via IN ('plan','contract') OR (a.via='paid' AND EXISTS(SELECT 1 FROM public.verification_orders o WHERE o.id=a.order_id AND o.status='paid')))))); $$;